function generate(rand, size) {
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 10);
  // A small value range forces many equal values; a wide one leaves few pairs.
  const span = rand() < 0.5 ? 1 + Math.floor(rand() * 4) : 1 + Math.floor(rand() * 100);
  const base = 1 + Math.floor(rand() * (101 - span));
  return [Array.from({ length: n }, () => base + Math.floor(rand() * span))];
}
